package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MutableDateTime.addHours(int)
 */
public class MutableDateTime_addHours_TriageGen2Test {

    @Test
    public void testAddHoursPositive() {
        // Initialize at a known time: 2023-01-01T10:00:00.000Z
        MutableDateTime dt = new MutableDateTime(1672567200000L);
        int hoursToAdd = 5;

        dt.addHours(hoursToAdd);

        // Expected: 2023-01-01T15:00:00.000Z
        assertEquals(1672585200000L, dt.getMillis());
        assertEquals(15, dt.getHourOfDay());
    }

    @Test
    public void testAddHoursNegative() {
        // Initialize at a known time: 2023-01-01T10:00:00.000Z
        MutableDateTime dt = new MutableDateTime(1672567200000L);
        int hoursToAdd = -3;

        dt.addHours(hoursToAdd);

        // Expected: 2023-01-01T07:00:00.000Z
        assertEquals(1672556400000L, dt.getMillis());
        assertEquals(7, dt.getHourOfDay());
    }

    @Test
    public void testAddHoursZero() {
        long initialMillis = 1672567200000L;
        MutableDateTime dt = new MutableDateTime(initialMillis);

        dt.addHours(0);

        assertEquals(initialMillis, dt.getMillis());
    }

    @Test
    public void testAddHoursCrossingDayBoundary() {
        // Initialize at 2023-01-01T23:00:00.000Z
        MutableDateTime dt = new MutableDateTime(1672570800000L);
        int hoursToAdd = 2;

        dt.addHours(hoursToAdd);

        // Expected: 2023-01-02T01:00:00.000Z
        assertEquals(2, dt.getDayOfMonth());
        assertEquals(1, dt.getHourOfDay());
    }

    @Test
    public void testAddHoursCrossingMonthBoundary() {
        // Initialize at 2023-01-31T22:00:00.000Z
        MutableDateTime dt = new MutableDateTime(1675202400000L);
        int hoursToAdd = 4;

        dt.addHours(hoursToAdd);

        // Expected: 2023-02-01T02:00:00.000Z
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
        assertEquals(2, dt.getHourOfDay());
    }

    @Test
    public void testAddHoursCrossingYearBoundary() {
        // Initialize at 2022-12-31T23:00:00.000Z
        MutableDateTime dt = new MutableDateTime(1672532400000L);
        int hoursToAdd = 2;

        dt.addHours(hoursToAdd);

        // Expected: 2023-01-01T01:00:00.000Z
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
        assertEquals(1, dt.getHourOfDay());
    }

    @Test
    public void testAddHoursLargeValue() {
        // Initialize at 2023-01-01T00:00:00.000Z
        MutableDateTime dt = new MutableDateTime(1672531200000L);
        // Add 24 * 365 days (roughly one year)
        int hoursToAdd = 24 * 365;

        dt.addHours(hoursToAdd);

        // Check if it moved approximately one year forward
        assertTrue(dt.getYear() >= 2024);
    }
}
